---SetCallBack
---设置单击回调函数
function WeekTasksMainCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function WeekTasksMainCellNode:Awake()
    SetButtonAction(self.FontStyleButton, function()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
    SetButtonAction(self.ImgIcon, function()
        GameUtils.ShowCommonTipsBoardAttribute(self.ImgIcon.gameObject, localize("扭蛋券"), localize("可从售货机内换取珍稀物品的扭蛋券。有效期极短，获取后需立刻使用。"))
        --GameUtils.ShowCommonTipsBoard(self.ImgIcon.gameObject, localize("扭蛋券"), localize("可从售货机内换取珍稀物品的扭蛋券。有效期极短，获取后需立刻使用。"), 5)
    end)

end

function WeekTasksMainCellNode:FreshBaseUI(data)
    self.TexDescribe.text = data.taskDesc
    self.TextNumber.text = "x"..data.callNum
    data.status = checkNumber(data.status)
    local isGet = data.status == Constants.GetStatus.Has
    KTool.SetActive(self.StateComplete, isGet)
    KTool.SetActive(self.StateNotComplete, not isGet)
    --self.TaskContentNode.alpha = isGet and 0.5 or 1
    local isAchieve = data.status == Constants.GetStatus.Can
    if not isGet then
        KTool.SetActive(self.StateOngoing, not isAchieve)
        KTool.SetActive(self.StateGashapon, isAchieve)
    end
    self.TextNumberProgress.text = string.format("(<size=30><color=#545454>%s</size></color>/%s)", data.progress, data.targetNum)
    self.ProgressBar.value = data.progress / data.targetNum
    CfUtils.SetUISwitchImage(self.Fill, isAchieve and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgFrame1, isAchieve and SwitchImageStatus.Can or SwitchImageStatus.Other)
    CfUtils.SetUISwitchImage(self.ImgFrame2, isAchieve and SwitchImageStatus.Can or SwitchImageStatus.Other)
end

function WeekTasksMainCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return WeekTasksMainCellNode